if(activeSettings==='notifications'){const n=s.notifications||{};page.innerHTML=settingHeader('Notifications','Orvia should feel present, not noisy. Important events can appear as compact iPhone-style banners.')+`<form class="ios-form" id="notificationsForm"><div class="ios-card"><div class="big-toggle"><div><b>Orvia notifications</b><small>Allow in-app banners and the notification center.</small></div><label class="switch"><input type="checkbox" name="enabled" ${n.enabled!==false?'checked':''}><span></span></label></div>${[['publishing','Publishing updates','Published, scheduled and delivery changes.'],['failures','Needs attention','Publishing errors, expired connections and blocked deliveries.'],['machine','Machine activity','Autonomous cycles starting, finishing or pausing.'],['connections','Account connections','A social account has connected, disconnected or needs attention.'],['weekly','Weekly growth summary','A calm recap of what changed in performance and learning.']].map(([k,t,d])=>`<label class="big-toggle"><div><b>${t}</b><small>${d}</small></div><input class="native-check" type="checkbox" name="${k}" ${n[k]?'checked':''}></label>`).join('')}<div class="quiet-hours"><label class="big-toggle"><div><b>Quiet hours</b><small>Suppress non-critical banners in your local time.</small></div><input class="native-check" type="checkbox" name="quietHours" ${n.quietHours?'checked':''}></label><div class="settings-fields two"><label>From<input name="quietStart" type="time" value="${esc(n.quietStart||'22:00')}"></label><label>Until<input name="quietEnd" type="time" value="${esc(n.quietEnd||'07:00')}"></label></div></div></div><div class="settings-save-bar"><span>Critical failures remain visible.</span><button class="primary-button">Save notification settings</button></div></form>`;$('#notificationsForm').onsubmit=saveNotifications;return}
