function timezoneOptions(){return['Africa/Lagos','UTC','America/New_York','America/Chicago','America/Denver','America/Los_Angeles','Europe/London','Europe/Paris','Asia/Dubai','Asia/Kolkata','Asia/Singapore','Asia/Tokyo','Australia/Sydney'].map(x=>`<option value="${x}">${x}</option>`).join('')}
function renderAdvanced(){
  const origin=location.origin.replace(/\/$/,'');
  const s=state.settings||{},c=state.config||{},adv=safeObj(state.advanced),con=safeObj(state.connections);
  const x=adv.xOAuth||{},yt=adv.youtube||{},me=adv.meta||{},tt=adv.tiktok||{},li=adv.linkedin||{},th=adv.threads||{},pi=adv.pinterest||{};
  return settingHeader('Advanced','Developer configuration lives here and nowhere else. Most Orvia users should never need this screen.')+
  `<div class="advanced-grid">
    <section class="advanced-card"><div class="form-section-title"><div><b>AI provider</b><small>OpenAI-compatible endpoint</small></div></div>
      <label>Base URL<input id="advAiBase" value="${esc(c.ai?.baseUrl||'https://api.openai.com/v1')}"></label>
      <label>Model<input id="advAiModel" value="${esc(c.ai?.model||'gpt-5.6-luna')}"></label>
      <label>API key<input id="advAiKey" type="password" placeholder="${c.ai?.configured?'Saved · leave blank to keep':'Enter API key'}"></label>
      <button class="mini-button primary" id="saveAi">Save AI provider</button>
    </section>
    <section class="advanced-card"><div class="form-section-title"><div><b>Research credentials</b><small>Tavily + X discovery</small></div></div>
      <label>Tavily API key<input id="advTavily" type="password" placeholder="${c.search?.configured?'Saved · leave blank to keep':'Enter API key'}"></label>
      <label>Monitored X accounts<input id="advXAccounts" value="${esc((c.xAccounts||[]).join(', '))}"></label>
      <label>X discovery Bearer token<input id="advXBearer" type="password" placeholder="${c.x?.discoveryConfigured?'Saved · leave blank to keep':'Enter bearer token'}"></label>
      <button class="mini-button primary" id="saveResearchSecrets">Save research</button>
    </section>
    <section class="advanced-card"><div class="form-section-title"><div><b>X OAuth app</b><small>Required once per Orvia deployment</small></div></div>
      <label>Client ID<input id="advXClientId" value="${esc(x.clientId||'')}"></label>
      <label>Client secret<input id="advXClientSecret" type="password" placeholder="Saved · leave blank to keep"></label>
      <label>Callback URI<input id="advXRedirect" value="${esc(x.redirectUri||`${origin}/api/publishing/x/connect`)}"></label>
      <label>Scopes<input id="advXScopes" value="${esc(x.scopes||'tweet.read tweet.write users.read offline.access')}"></label>
      <button class="mini-button primary" id="saveXConfig">Save X setup</button>
    </section>
    <section class="advanced-card"><div class="form-section-title"><div><b>YouTube</b><small>Google OAuth application</small></div></div>
      <label>Client ID<input id="advYTClientId" value="${esc(yt.clientId||'')}"></label>
      <label>Client secret<input id="advYTClientSecret" type="password" placeholder="Saved · leave blank to keep"></label>
      <label>Callback URI<input id="advYTRedirect" value="${esc(yt.redirectUri||`${origin}/api/publishing/youtube/callback`)}"></label>
      <button class="mini-button primary" id="saveYTConfig">Save YouTube setup</button>
    </section>
    <section class="advanced-card"><div class="form-section-title"><div><b>Meta</b><small>Instagram + Facebook Pages</small></div></div>
      <label>App ID<input id="advMetaId" value="${esc(me.clientId||'')}"></label>
      <label>App secret<input id="advMetaSecret" type="password" placeholder="Saved · leave blank to keep"></label>
      <label>Callback URI<input id="advMetaRedirect" value="${esc(me.redirectUri||`${origin}/api/publishing/meta/callback`)}"></label>
      <label>Graph version<input id="advMetaVersion" value="${esc(me.graphVersion||'v24.0')}"></label>
      <button class="mini-button primary" id="saveMetaConfig">Save Meta setup</button>
    </section>
    <section class="advanced-card"><div class="form-section-title"><div><b>TikTok</b><small>Content Posting API</small></div></div>
      <label>Client key<input id="advTTKey" value="${esc(tt.clientKey||'')}"></label>
      <label>Client secret<input id="advTTSecret" type="password" placeholder="Saved · leave blank to keep"></label>
      <label>Callback URI<input id="advTTRedirect" value="${esc(tt.redirectUri||`${origin}/api/publishing/tiktok/callback`)}"></label>
      <button class="mini-button primary" id="saveTTConfig">Save TikTok setup</button>
    </section>
    <section class="advanced-card"><div class="form-section-title"><div><b>LinkedIn</b><small>Member publishing</small></div></div>
      <label>Client ID<input id="advLIId" value="${esc(li.clientId||'')}"></label>
      <label>Client secret<input id="advLISecret" type="password" placeholder="Saved · leave blank to keep"></label>
      <label>Callback URI<input id="advLIRedirect" value="${esc(li.redirectUri||`${origin}/api/publishing/linkedin/callback`)}"></label>
      <label>API version<input id="advLIVersion" value="${esc(li.version||'202601')}"></label>
      <button class="mini-button primary" id="saveLIConfig">Save LinkedIn setup</button>
    </section>
    <section class="advanced-card"><div class="form-section-title"><div><b>Threads</b><small>Meta Threads API</small></div></div>
      <label>App ID<input id="advTHId" value="${esc(th.clientId||'')}"></label>
      <label>App secret<input id="advTHSecret" type="password" placeholder="Saved · leave blank to keep"></label>
      <label>Callback URI<input id="advTHRedirect" value="${esc(th.redirectUri||`${origin}/api/publishing/threads/callback`)}"></label>
      <button class="mini-button primary" id="saveTHConfig">Save Threads setup</button>
    </section>
    <section class="advanced-card"><div class="form-section-title"><div><b>Pinterest</b><small>API v5</small></div></div>
      <label>App ID<input id="advPINId" value="${esc(pi.clientId||'')}"></label>
      <label>Client secret<input id="advPINSecret" type="password" placeholder="Saved · leave blank to keep"></label>
      <label>Callback URI<input id="advPINRedirect" value="${esc(pi.redirectUri||`${origin}/api/publishing/pinterest/callback`)}"></label>
      <button class="mini-button primary" id="savePINConfig">Save Pinterest setup</button>
    </section>
  </div>`;
}
function safeObj(v){return(v&&typeof v==='object')?v:{}}
function bindAdvanced(){const save=(provider,values,msg)=>jsonPost('/api/settings/provider',{provider,values}).then(()=>{notify('SETTINGS',`${msg} saved`,'Orvia stored the provider configuration securely.');load()}).catch(e=>notify('SETTINGS',`${msg} failed`,e.message,'warning'));$('#saveAi').onclick=()=>jsonPost('/api/settings/config',{aiBaseUrl:$('#advAiBase').value,aiModel:$('#advAiModel').value,aiApiKey:$('#advAiKey').value}).then(()=>notify('SETTINGS','AI provider saved','The intelligence layer is configured.')).then(load).catch(e=>notify('SETTINGS','AI setup failed',e.message,'warning'));$('#saveResearchSecrets').onclick=()=>jsonPost('/api/settings/config',{tavilyApiKey:$('#advTavily').value,xAccounts:$('#advXAccounts').value,xBearerToken:$('#advXBearer').value}).then(()=>notify('SETTINGS','Research sources saved','Discovery configuration is up to date.')).then(load).catch(e=>notify('SETTINGS','Research setup failed',e.message,'warning'));$('#saveXConfig').onclick=()=>save('xOAuthConfig',{clientId:$('#advXClientId').value,clientSecret:$('#advXClientSecret').value,redirectUri:$('#advXRedirect').value,scopes:$('#advXScopes').value},'X setup');$('#saveYTConfig').onclick=()=>save('youtubeConfig',{clientId:$('#advYTClientId').value,clientSecret:$('#advYTClientSecret').value,redirectUri:$('#advYTRedirect').value},'YouTube setup');$('#saveMetaConfig').onclick=()=>save('metaConfig',{clientId:$('#advMetaId').value,clientSecret:$('#advMetaSecret').value,redirectUri:$('#advMetaRedirect').value,graphVersion:$('#advMetaVersion').value},'Meta setup');$('#saveTTConfig').onclick=()=>save('tiktokConfig',{clientKey:$('#advTTKey').value,clientSecret:$('#advTTSecret').value,redirectUri:$('#advTTRedirect').value},'TikTok setup');$('#saveLIConfig').onclick=()=>save('linkedinConfig',{clientId:$('#advLIId').value,clientSecret:$('#advLISecret').value,redirectUri:$('#advLIRedirect').value,version:$('#advLIVersion').value},'LinkedIn setup');$('#saveTHConfig').onclick=()=>save('threadsConfig',{clientId:$('#advTHId').value,clientSecret:$('#advTHSecret').value,redirectUri:$('#advTHRedirect').value},'Threads setup');$('#savePINConfig').onclick=()=>save('pinterestConfig',{clientId:$('#advPINId').value,clientSecret:$('#advPINSecret').value,redirectUri:$('#advPINRedirect').value},'Pinterest setup')}
async function saveMediaSettings(e){e.preventDefault();const f=new FormData(e.target);try{await jsonPost('/api/settings/media',{assetBaseUrl:f.get('assetBaseUrl'),defaultImageUrl:f.get('defaultImageUrl'),defaultVideoUrl:f.get('defaultVideoUrl')});notify('SETTINGS','Media settings saved','Orvia has updated its public asset defaults.');await load()}catch(err){notify('SETTINGS','Media settings failed',err.message,'warning')}}
async function addAsset(e){e.preventDefault();const f=new FormData(e.target);try{await jsonPost('/api/media/assets',{name:f.get('name'),url:f.get('url'),kind:f.get('kind')});notify('MEDIA','Asset added','The public asset is now available on your Orvia shelf.');e.target.reset();await load();renderSettingsPage()}catch(err){notify('MEDIA','Asset could not be added',err.message,'warning')}}
async function removeAsset(id){try{await api(`/api/media/assets/${encodeURIComponent(id)}`,{method:'DELETE'});notify('MEDIA','Asset removed','The reusable asset was removed from Orvia.');await load();renderSettingsPage()}catch(err){notify('MEDIA','Asset removal failed',err.message,'warning')}}
async function saveProfile(e){e.preventDefault();const f=new FormData(e.target);try{await jsonPost('/api/settings/profile',{name:f.get('name'),tagline:f.get('tagline'),bio:f.get('bio'),website:f.get('website'),location:f.get('location'),languages:String(f.get('languages')||'').split(',').map(x=>x.trim()).filter(Boolean)});notify('SETTINGS','Creator profile saved','Your publishing identity is up to date.');await load()}catch(err){notify('SETTINGS','Profile save failed',err.message,'warning')}}
async function saveStrategy(e){e.preventDefault();const f=new FormData(e.target);const parse=x=>String(x||'').split(/[\n,]/).map(v=>v.trim()).filter(Boolean);const formats=[...$$('#strategyForm input[name="formats"]')].filter(x=>x.checked).map(x=>x.value);try{await jsonPost('/api/settings/strategy',{primaryTopics:parse(f.get('primaryTopics')),secondaryTopics:parse(f.get('secondaryTopics')),avoidTopics:parse(f.get('avoidTopics')),formats,contentMix:{news:Number(f.get('mixNews')),education:Number(f.get('mixEducation')),opinion:Number(f.get('mixOpinion')),stories:Number(f.get('mixStories'))}});notify('SETTINGS','Content strategy saved','Future intelligence cycles will use the new editorial direction.');await load()}catch(err){notify('SETTINGS','Strategy save failed',err.message,'warning')}}
async function saveResearch(e){e.preventDefault();const f=new FormData(e.target);try{await jsonPost('/api/settings/config',{searchProvider:f.get('searchProvider'),queries:f.get('queries'),xAccounts:f.get('xAccounts')});notify('SETTINGS','Research setup saved','Orvia will use the new discovery inputs.');await load()}catch(err){notify('SETTINGS','Research save failed',err.message,'warning')}}
async function saveAutomation(e){e.preventDefault();const f=new FormData(e.target);try{await jsonPost('/api/settings/automation',{enabled:f.get('enabled')==='on',cycleMinutes:Number(f.get('cycleMinutes')),createContent:f.get('createContent')==='on',autoApproveContent:f.get('autoApproveContent')==='on',autoPublish:f.get('autoPublish')==='on'});notify('SETTINGS','Automation saved','The machine will use the new operating mode.');await load()}catch(err){notify('SETTINGS','Automation save failed',err.message,'warning')}}
async function savePreferences(e){e.preventDefault();const f=new FormData(e.target);try{await jsonPost('/api/settings/preferences',{defaultDestinations:[...$$('#preferencesForm input[name="destinations"]')].filter(x=>x.checked).map(x=>x.value),reviewMode:f.get('reviewMode'),adaptiveScheduling:f.get('adaptiveScheduling')==='on',crossPlatformAdaptation:f.get('crossPlatformAdaptation')==='on',duplicateProtection:f.get('duplicateProtection')==='on'});notify('SETTINGS','Publishing preferences saved','Orvia will apply the new routing defaults.');await load()}catch(err){notify('SETTINGS','Preference save failed',err.message,'warning')}}
async function saveSchedule(e){e.preventDefault();const f=new FormData(e.target);try{await jsonPost('/api/settings/timezone',{timezone:f.get('timezone')});notify('SETTINGS','Timezone saved',`Schedules will use ${f.get('timezone')}.`);await load()}catch(err){notify('SETTINGS','Timezone save failed',err.message,'warning')}}
async function saveNotifications(e){e.preventDefault();const f=new FormData(e.target);try{await jsonPost('/api/settings/notifications',{enabled:f.get('enabled')==='on',publishing:f.get('publishing')==='on',failures:f.get('failures')==='on',machine:f.get('machine')==='on',connections:f.get('connections')==='on',weekly:f.get('weekly')==='on',quietHours:f.get('quietHours')==='on',quietStart:f.get('quietStart'),quietEnd:f.get('quietEnd')});notify('SETTINGS','Notifications saved','Orvia will use your new notification preferences.');await load()}catch(err){notify('SETTINGS','Notification save failed',err.message,'warning')}}
function connectionEndpoint(name){const map={'X':'x','YouTube':'youtube','Instagram':'meta','Facebook Pages':'meta','TikTok':'tiktok','LinkedIn':'linkedin','Threads':'threads','Pinterest':'pinterest'};return map[name]}
function bindConnectionActions(){$$('[data-connect]').forEach(b=>b.onclick=()=>{const name=b.dataset.connect;if(['Instagram','Facebook Pages'].includes(name)&&!state.connections?.Meta?.configured){activeSettings='advanced';renderSettingsPage();return}const slug=connectionEndpoint(name);if(slug==='x')window.location.href='/api/publishing/x/connect';else window.location.href=`/api/publishing/${slug}/connect`});$$('[data-verify]').forEach(b=>b.onclick=async()=>{try{const slug=connectionEndpoint(b.dataset.verify);const r=await jsonPost(`/api/connections/${slug==='x'?'X':b.dataset.verify}/verify`);notify('CONNECTION','Connection verified',`${b.dataset.verify} is responding normally.`);await load()}catch(e){notify('CONNECTION','Verification failed',e.message,'warning')}});$$('[data-disconnect]').forEach(b=>b.onclick=async()=>{try{const slug=connectionEndpoint(b.dataset.disconnect);await jsonPost(`/api/connections/${slug==='x'?'X':b.dataset.disconnect}/disconnect`);notify('CONNECTION',`${b.dataset.disconnect} disconnected`,'The publishing permission was removed from Orvia.','warning');await load()}catch(e){notify('CONNECTION','Disconnect failed',e.message,'warning')}});$$('[data-open-advanced]').forEach(b=>b.onclick=()=>{activeSettings='advanced';renderSettingsPage()})}
async function disconnectAll(){if(!confirm('Disconnect all publishing accounts from Orvia?'))return;for(const name of ['X','YouTube','Meta','TikTok','LinkedIn','Threads','Pinterest']){try{await jsonPost(`/api/connections/${name}/disconnect`)}catch{}}notify('SECURITY','Publishing accounts disconnected','Orvia no longer has publishing access.','warning');await load();renderSettingsPage()}
function renderDistribution(box){const items=state.distribution||[];box.innerHTML=`<div class="workspace-toolbar"><div><b>${items.length}</b><span>distribution items</span></div><button class="mini-button" id="refreshDistribution">Refresh</button></div><div class="distribution-list">${items.map(d=>`<article class="dist-item"><div class="connection-logo">${platformLabel(d.platform)}</div><div class="dist-copy"><b>${esc(d.title)}</b><small>${esc(d.platform)} · ${esc(d.type||'Draft')} · ${d.status==='scheduled'?fmtDate(d.scheduledAt):esc(d.status)}</small>${d.lastError?`<span class="dist-error">${esc(d.lastError)}</span>`:''}</div><span class="dist-state ${d.status}">${esc(d.status)}</span><div class="dist-actions">${['queued','ready','failed'].includes(d.status)?`<button class="mini-button primary" data-publish="${d.id}">Publish</button>`:''}${['queued','ready','failed'].includes(d.status)?`<button class="mini-button" data-schedule="${d.id}">Schedule</button>`:''}${['queued','scheduled','ready','failed'].includes(d.status)?`<button class="mini-button quiet" data-cancel="${d.id}">Cancel</button>`:''}</div></article>`).join('')||'<div class="empty-state"><b>No distribution items</b><small>Approve a package and queue it for connected destinations.</small></div>'}</div>`;$('#refreshDistribution').onclick=()=>load();$$('[data-publish]').forEach(b=>b.onclick=()=>publishItem(b.dataset.publish));$$('[data-schedule]').forEach(b=>b.onclick=()=>openScheduleEditor(b.dataset.schedule));$$('[data-cancel]').forEach(b=>b.onclick=()=>cancelItem(b.dataset.cancel))}
async function publishItem(id){try{await jsonPost('/api/distribution/publish',{distributionId:id});notify('DISTRIBUTION','Published successfully','The platform confirmed the post.');await load();renderDistribution($('#operationBody'))}catch(e){notify('DISTRIBUTION','Publishing needs attention',e.message,'warning');await load();renderDistribution($('#operationBody'))}}
async function cancelItem(id){try{await jsonPost('/api/distribution/cancel',{distributionId:id});notify('DISTRIBUTION','Distribution cancelled','The item was removed from the publishing path.','warning');await load();renderDistribution($('#operationBody'))}catch(e){notify('DISTRIBUTION','Cancel failed',e.message,'warning')}}
function timezoneOffsetMs(date,tz){const parts=new Intl.DateTimeFormat('en-US',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(date),o={};parts.forEach(p=>o[p.type]=p.value);return Date.UTC(Number(o.year),Number(o.month)-1,Number(o.day),Number(o.hour),Number(o.minute),Number(o.second))-date.getTime()}
function zonedDateTimeToISO(value,tz){const [dp,tp]=String(value||'').split('T');if(!dp||!tp)throw new Error('Choose a valid date and time.');const [y,m,d]=dp.split('-').map(Number),[hh,mm]=tp.split(':').map(Number);let guess=Date.UTC(y,m-1,d,hh,mm,0);for(let i=0;i<4;i++)guess=Date.UTC(y,m-1,d,hh,mm,0)-timezoneOffsetMs(new Date(guess),tz);return new Date(guess).toISOString()}
function openScheduleEditor(id){const item=(state.distribution||[]).find(x=>x.id===id);if(!item)return;const tz=state.settings?.timezone||'Africa/Lagos',next=new Date(Date.now()+60*60*1000),parts=new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(next),m={};parts.forEach(x=>m[x.type]=x.value);const value=`${m.year}-${m.month}-${m.day}T${m.hour}:${m.minute}`,modal=document.createElement('div');modal.className='schedule-popover';modal.innerHTML=`<div class="schedule-panel"><button class="schedule-close" aria-label="Close">×</button><small>SCHEDULE DESTINATION</small><h3>${esc(item.title)}</h3><label>Publish date & time<input id="scheduleDate" type="datetime-local" value="${value}"></label><label>Time zone<input id="scheduleTz" list="scheduleZones" value="${esc(tz)}"><datalist id="scheduleZones">${timezoneOptions()}</datalist></label><p>Orvia stores the schedule in UTC and displays it using your selected time zone.</p><div class="schedule-actions"><button class="secondary-button" id="scheduleCancel">Cancel</button><button class="primary-button" id="scheduleSave">Schedule</button></div></div>`;document.body.appendChild(modal);const close=()=>modal.remove();modal.querySelector('.schedule-close').onclick=close;modal.querySelector('#scheduleCancel').onclick=close;modal.onclick=e=>{if(e.target===modal)close()};modal.querySelector('#scheduleSave').onclick=async()=>{try{const zone=modal.querySelector('#scheduleTz').value.trim();const date=modal.querySelector('#scheduleDate').value;const iso=zonedDateTimeToISO(date,zone);await jsonPost('/api/distribution/schedule',{distributionId:id,scheduledAt:iso});close();notify('DISTRIBUTION','Post scheduled',`${fmtDate(iso)} · ${zone}`);await load();renderDistribution($('#operationBody'))}catch(e){notify('DISTRIBUTION','Schedule failed',e.message,'warning')}}}
function renderGrowth(box){const l=state.learning||{},tot=l.totals||{};box.innerHTML=`<div class="insight-grid"><section class="insight-card"><small>PERFORMANCE EVIDENCE</small><b>${(state.analytics||[]).length}</b><span>records</span></section><section class="insight-card"><small>ENGAGEMENT RATE</small><b>${pct(l.engagementRate||0)}</b><span>from recorded reach</span></section><section class="insight-card"><small>CLICK RATE</small><b>${pct(l.clickRate||0)}</b><span>from recorded reach</span></section><section class="insight-card"><small>CONVERSIONS</small><b>${Number(tot.conversions||0).toLocaleString()}</b><span>verified records</span></section></div><section class="ios-card"><div class="form-section-title"><div><b>${esc(l.title||'Learning is waiting.')}</b><small>${esc(l.summary||'')}</small></div><button class="mini-button" id="refreshLearning">Refresh learning</button></div><div class="learning-patterns">${(l.patterns||[]).map(x=>`<div><i>✦</i><span>${esc(x)}</span></div>`).join('')||'<div class="empty-state"><b>Not enough evidence yet</b><small>Publish or record performance before Orvia changes its strategy.</small></div>'}</div></section>`;$('#refreshLearning').onclick=async()=>{await jsonPost('/api/learning/refresh');notify('GROWTH','Learning refreshed','Orvia recomputed patterns from recorded evidence.');await load();renderGrowth($('#operationBody'))}}
function renderRevenue(box){const revenue=state.revenue||[];box.innerHTML=`<div class="revenue-total"><small>RECORDED REVENUE</small><b>$${revenue.reduce((n,x)=>n+Number(x.amount||0),0).toLocaleString(undefined,{maximumFractionDigits:2})}</b></div><form class="ios-card record-form" id="revenueForm"><label>Source<select name="source"><option>Sponsorship</option><option>Affiliate</option><option>Product</option><option>Service</option><option>Other</option></select></label><label>Amount<input name="amount" type="number" step="0.01" min="0" placeholder="0.00"></label><label class="full">Description<input name="description" placeholder="What generated the revenue?"></label><button class="primary-button full" type="submit">Record revenue</button></form><div class="ledger-list">${revenue.slice(0,20).map(x=>`<div><span>${esc(x.source)}</span><b>${esc(x.currency||'USD')} ${Number(x.amount||0).toFixed(2)}</b><small>${fmtDate(x.recordedAt)}</small></div>`).join('')||'<div class="empty-state"><b>No revenue recorded</b><small>Orvia will never invent monetization numbers.</small></div>'}</div>`;$('#revenueForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await jsonPost('/api/revenue/record',{source:f.get('source'),amount:f.get('amount'),description:f.get('description')});notify('REVENUE','Revenue recorded',`$${Number(f.get('amount')).toFixed(2)} · ${f.get('source')}`);e.target.reset();await load();renderRevenue($('#operationBody'))}catch(err){notify('REVENUE','Record failed',err.message,'warning')}}}
function renderIntelligence(box){const runs=state.runs||[],signals=state.signals||[];box.innerHTML=`<div class="insight-grid"><section class="insight-card"><small>RUNS</small><b>${runs.length}</b><span>stored cycles</span></section><section class="insight-card"><small>SIGNALS</small><b>${signals.length}</b><span>stored evidence</span></section><section class="insight-card"><small>OPPORTUNITIES</small><b>${(state.opportunities||[]).length}</b><span>ranked</span></section><section class="insight-card"><small>MACHINE</small><b>${state.machineActive?'ON':'OFF'}</b><span>${state.automationBusy?'working now':'idle'}</span></section></div><section class="ios-card timeline-card"><div class="form-section-title"><div><b>Latest intelligence cycles</b><small>Scout → Research → Orvia Brain</small></div><button class="mini-button" id="runIntelFromView">Run cycle</button></div>${runs.slice(0,12).map(r=>`<div class="timeline-row"><span class="timeline-dot"></span><div><b>${esc(r.status||'completed')}</b><small>${fmtDate(r.createdAt)} · ${fmtDuration(r.durationMs)} · ${Number(r.opportunities||0)} opportunities</small></div></div>`).join('')||'<div class="empty-state"><b>No cycles yet</b><small>Run an intelligence cycle to begin.</small></div>'}</section>`;$('#runIntelFromView').onclick=()=>{closeOperation();run()}}
function renderLibrary(box){const items=state.content||[];box.innerHTML=`<div class="library-grid">${items.map(x=>`<article class="library-card"><div><span>${esc(x.status||'review')}</span><small>${fmtDate(x.createdAt)}</small></div><h3>${esc(x.package?.hook||x.package?.thesis||'Content package')}</h3><p>${esc(x.package?.thesis||'')}</p><button class="mini-button" data-library="${x.id}">Open Factory</button></article>`).join('')||'<div class="empty-state"><b>Your library is empty</b><small>Generate a package from any opportunity.</small></div>'}</div>`;$$('[data-library]').forEach(b=>b.onclick=()=>{closeOperation();openFactory(state.content.find(x=>x.id===b.dataset.library)?.opportunityId)})}
async function runAutoNow(){try{notify('ORVIA','Operation started','Scout → Research → Content → Distribution is moving.','success',{duration:4200});await jsonPost('/api/machine/run');await load();notify('ORVIA','Operation complete','The latest media cycle has finished.')}catch(e){notify('ORVIA','Autonomous cycle failed',e.message,'warning')}}
function handleOAuthReturn(){const p=new URLSearchParams(location.search);if(p.get('connected')){const name={x:'X',youtube:'YouTube',meta:'Meta',tiktok:'TikTok',linkedin:'LinkedIn',threads:'Threads',pinterest:'Pinterest'}[p.get('connected')]||p.get('connected');notify('CONNECTION',`${name} connected`,`${name} is now available inside Orvia.`);history.replaceState({},'',location.pathname)}if(p.get('connect_error')){notify('CONNECTION','Connection could not be completed',p.get('connect_error'),'warning');history.replaceState({},'',location.pathname)}}
$('#run').onclick=run;$('#contentBtn').onclick=()=>openFactory(state?.opportunities?.[0]?.id);$('#pipelineBtn').onclick=()=>openFactory(state?.opportunities?.[0]?.id);$('#viewAll').onclick=()=>openFactory(state?.opportunities?.[0]?.id);$('#closeFactory').onclick=closeFactory;$('#closeOperation').onclick=closeOperation;$('#factoryModal').onclick=e=>{if(e.target.id==='factoryModal')closeFactory()};$('#operationModal').onclick=e=>{if(e.target.id==='operationModal')closeOperation()};document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeFactory();closeOperation()}});
$('#machineSide').onclick=async()=>{const next=!machineActive;try{await jsonPost('/api/machine/toggle',{active:next});await load();notify('ORVIA',next?'Operation resumed':'Operation paused',next?'Autonomous operation is active again.':'Automatic cycles have been stopped.',next?'success':'warning')}catch(e){notify('SYSTEM','Machine toggle failed',e.message,'warning')}};
function applyTheme(t){const light=t==='light';document.body.classList.toggle('light',light);$('#themeIcon').textContent=light?'☀':'☾';localStorage.setItem('orvia-theme',t)}$('#theme').onclick=()=>applyTheme(document.body.classList.contains('light')?'dark':'light');applyTheme(localStorage.getItem('orvia-theme')==='light'?'light':'dark');
function renderNotificationCenter(){const box=$('#notificationCenterList');if(!box)return;const items=state?.notifications||[];box.innerHTML=items.length?items.map(n=>`<div class="center-notification ${n.read?'read':''}" data-notification-id="${esc(n.id)}" role="button" tabindex="0"><span class="center-icon ${esc(n.kind||'info')}">${esc(notificationIcon(n.source||'ORVIA',n.kind==='warning'?'warning':'success'))}</span><span class="center-copy"><span class="center-meta"><b>${esc(n.source||'ORVIA')}</b><small>${fmtDate(n.createdAt)}</small></span><strong>${esc(n.title)}</strong><small>${esc(n.description)}</small>${n.action==='media-settings'?'<span class="center-action">Open Media & Generation <b>›</b></span>':''}</span><span class="center-state">${n.read?'':'●'}</span></div>`).join(''):'<div class="empty-state notification-empty"><span class="empty-icon">◒</span><b>You’re all caught up</b><small>Orvia will place important events here.</small></div>';$$('[data-notification-id]').forEach(b=>{const open=async()=>{if(b.dataset.notificationId){if(!b.classList.contains('read'))await jsonPost('/api/notifications/read',{id:b.dataset.notificationId});const n=items.find(x=>x.id===b.dataset.notificationId);if(n?.action==='media-settings'){closeNotificationCenter();activeSettings='media';openOperation('settings')}await load();if(document.querySelector('#notificationCenter.open'))renderNotificationCenter();}};b.onclick=open;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' ') {e.preventDefault();open()}}})}
function openNotificationCenter(){renderNotificationCenter();const el=$('#notificationCenter');el.classList.add('open');el.setAttribute('aria-hidden','false');}
function closeNotificationCenter(){const el=$('#notificationCenter');el.classList.remove('open');el.setAttribute('aria-hidden','true');}
$('#notificationButton')?.addEventListener('click',openNotificationCenter);
$('#notificationCenterClose')?.addEventListener('click',closeNotificationCenter);$('#notificationCenterBackdrop')?.addEventListener('click',closeNotificationCenter);
$('#notificationMarkAll')?.addEventListener('click',async()=>{await jsonPost('/api/notifications/read');await load();renderNotificationCenter()});
$$('.nav-item').forEach(b=>b.onclick=()=>{$$('.nav-item').forEach(x=>{x.classList.remove('active');x.removeAttribute('aria-current')});b.classList.add('active');b.setAttribute('aria-current','page');const v=b.dataset.view;if(v==='home'){closeOperation();return}openOperation(v)});
handleOAuthReturn();load();if(!sessionStorage.getItem('orvia-notification-welcome')){setTimeout(()=>notify('ORVIA','Orvia is ready','Your media operation is running in the background.','success',{duration:5200}),900);sessionStorage.setItem('orvia-notification-welcome','1')}setInterval(load,15000);
